'use strict';

// MODULES //

var typedarray2json = require( '@stdlib/array/to-json' );


// MAIN //

/**
* Serializes a one-sample t-test results object as a JSON object.
*
* @param {Object} results - one-sample t-test results object
* @returns {Object} serialized object
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var results = {
*     'rejected': true,
*     'alpha': 0.05,
*     'pValue': 0.0031,
*     'statistic': 4.0,
*     'df': 9.0,
*     'nullValue': 0.0,
*     'mean': 1.2,
*     'sd': 0.3,
*     'ci': new Float64Array( [ 0.5214, 1.8786 ] ),
*     'alternative': 'two-sided',
*     'method': 'One-sample t-test'
* };
*
* var obj = toJSON( results );
* // returns {...}
*/
function toJSON( results ) {
	return {
		'rejected': results.rejected,
		'alpha': results.alpha,
		'pValue': results.pValue,
		'statistic': results.statistic,
		'df': results.df,
		'nullValue': results.nullValue,
		'mean': results.mean,
		'sd': results.sd,
		'ci': typedarray2json( results.ci ),
		'alternative': results.alternative,
		'method': results.method
	};
}


// EXPORTS //

module.exports = toJSON;
